local _G = _G
local Players = game:GetService("Players")
local LP = Players.LocalPlayer

-- license token (matches the main's authOk gate: (35596*77777)+63303)
local __lic = (0x8B0C * 0x12FD1) + 0xF747
if typeof(getgenv) == "function" then getgenv().__ZINKA_LIC = __lic end
rawset(_G, "__ZINKA_LIC", __lic)
_G.__ZINKA_LIC = __lic

if rawget(_G, "__ZINKA_LOADER_RAN") then return end
rawset(_G, "__ZINKA_LOADER_RAN", true)

local __b64 = [[]]

local bit32 = bit32
local band = bit32.band
local bxor = bit32.bxor
local lshift = bit32.lshift
local rshift = bit32.rshift
local M = 0x100000000

-- ---- base64 -> byte array ----
local function b64decode(s)
    local CH = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local t = {}
    local n = 0
    local acc, bits = 0, 0
    for i = 1, #s do
        local c = s:sub(i, i)
        if c == "=" then break end
        local v = CH:find(c, 1, true)
        if v then v = v - 1 end
        acc = acc * 64 + v
        bits = bits + 6
        if bits >= 8 then
            bits = bits - 8
            n = n + 1
            t[n] = math.floor(acc / (2 ^ bits)) % 256
            acc = acc % (2 ^ bits)
        end
    end
    return t, n
end

local __ke = { 0x5A91C32E, 0x7708B4D1, 0x3FE26A19, 0x8B321921 }
local __delta = 0x9E3779B9

-- XTEA-32/CBC block decrypt (exact inverse of the encoder)
local function xteaDec(b)
    local v0 = b[1] + b[2] * 0x100 + b[3] * 0x10000 + b[4] * 0x1000000
    local v1 = b[5] + b[6] * 0x100 + b[7] * 0x10000 + b[8] * 0x1000000
    local s = (__delta * 0x20) % M
    for _ = 1, 32 do
        local fe = bxor(lshift(v0, 4), rshift(v0, 5))
        local k0 = (s + __ke[(math.floor(s / 0x800) % 4) + 1]) % M
        v1 = (v1 - bxor((fe + v0) % M, k0)) % M
        local fe2 = bxor(lshift(v1, 4), rshift(v1, 5))
        local k1 = (s + __ke[(s % 4) + 1]) % M
        v0 = (v0 - bxor((fe2 + v1) % M, k1)) % M
        s = (s - __delta) % M
    end
    return v0, v1
end

local __xor = { 0x7A, 0x3F, 0x91, 0xC4, 0x18, 0xE2, 0x5D, 0x8B, 0x33, 0xA7, 0x6E, 0xD0 }

-- ---- decode ----
local raw, rn = b64decode(__b64)
local dec = {}
local pv0, pv1 = 0, 0
local i = 1
while i + 7 <= rn do
    local c0 = raw[i] + raw[i+1] * 0x100 + raw[i+2] * 0x10000 + raw[i+3] * 0x1000000
    local c1 = raw[i+4] + raw[i+5] * 0x100 + raw[i+6] * 0x10000 + raw[i+7] * 0x1000000
    local b = { raw[i], raw[i+1], raw[i+2], raw[i+3], raw[i+4], raw[i+5], raw[i+6], raw[i+7] }
    local v0, v1 = xteaDec(b)
    v0 = bxor(v0, pv0)
    v1 = bxor(v1, pv1)
    pv0, pv1 = c0, c1
    for k = 0, 3 do dec[#dec + 1] = band(rshift(v0, k * 8), 0xFF) end
    for k = 0, 3 do dec[#dec + 1] = band(rshift(v1, k * 8), 0xFF) end
    i = i + 8
end

-- stream XOR decode
local kl = #__xor
local acc = 0x5A
local full = {}
for i = 1, #dec do
    local enc = dec[i]
    local kv = __xor[((i - 1) % kl) + 1]
    local d = bxor(bxor(bxor(enc, kv), acc % 0x100), ((i - 1) * 0x11) % 0x100)
    full[i] = string.char(d)
    acc = (acc + enc + kv) % 0x100
end
local s = table.concat(full)

-- strip PKCS7 padding (appended before XTEA)
local pad = string.byte(s, #s) or 0
if pad >= 1 and pad <= 8 then
    local ok = true
    for j = 0, pad - 1 do
        if (string.byte(s, #s - j) or 0) ~= pad then ok = false break end
    end
    if ok then s = s:sub(1, #s - pad) end
end

local fn, err = loadstring(s)
if not fn then
    warn("[ZINKA] loader decode failed: " .. tostring(err))
    return
end
fn()
